// Boat models, base64-encoded GLB.
//
// GENERATED by tools/pack-boats.mjs -- do not edit by hand.
//
// The originals are ~3.5 MB each, almost entirely one baseColor JPEG; the
// geometry is only about 10k vertices. Downscaled to 512px at quality
// 0.82, the set fits in a self-contained page with room to spare. They
// are inlined rather than fetched because the artifact is one file under a CSP
// that blocks external hosts.

export const BOATS = [
	{ id: 'burrito', label: 'Burrito', glb: '' },
	{ id: 'pirate', label: 'Pirate', glb: '' },
	{ id: 'racingred', label: 'Racingred', glb: '' },
	{ id: 'inflatable', label: 'Inflatable', glb: '' },
	{ id: 'yacht', label: 'Yacht', glb: '' },
];

/** Decode one model's GLB to an ArrayBuffer for GLTFLoader.parse(). */
export function glbBuffer( b64 ) {

	const bin = atob( b64 );
	const out = new Uint8Array( bin.length );
	for ( let i = 0; i < bin.length; i ++ ) out[ i ] = bin.charCodeAt( i );
	return out.buffer;

}
